  ('d0c00015-0000-4000-8000-000000000003', 'New MRI 3T machine operational', 'Radiology has commissioned a new 3 Tesla MRI. Slots can now be booked through the front desk.', 'all', 'normal', (current_date + -6), default, default, default, ((current_date + -6) + time '12:00')),
  ('d0c00015-0000-4000-8000-000000000004', 'CME: Updates in diabetes management', 'Continuing medical education session by Dr. Pooja Bansal on Friday, 4 PM, Conference Hall B.', 'doctors', 'normal', (current_date + -4), default, default, 'Neha Kapoor', ((current_date + -4) + time '15:00')),
  ('d0c00015-0000-4000-8000-000000000005', 'Online reports now available', 'Patients can now view their lab results, prescriptions and invoices directly from the patient portal.', 'patients', 'normal', (current_date + -8), default, default, default, ((current_date + -8) + time '11:00')),
  ('d0c00015-0000-4000-8000-000000000006', 'Night shift roster updated', 'The revised night shift roster for nursing staff is available with the Head Nurse.', 'staff', 'normal', (current_date + -10), default, default, default, ((current_date + -10) + time '17:00'));

