  on conflict (tenant_id, key) do nothing;
end $$;
revoke all on function public.seed_hospital_defaults(uuid) from public, anon, authenticated;

-- ------------------------------------------------------------------ product page leads (phase 2.2)
-- "Talk to us" form on the Hospital Comrade product page (the platform domain). Platform-level: no tenant_id, only
-- Hospital Comrade admins can read or update them; visitors can only add one through submit_platform_lead().
create table if not exists public.platform_leads (
  id            uuid primary key default gen_random_uuid(),
  created_at    timestamptz not null default now(),
  name          text not null check (char_length(name) between 2 and 100),
  organisation  text not null check (char_length(organisation) between 2 and 150),
  phone         text not null check (phone ~ '^\+?[0-9]{10,13}$'),
  email         text check (email is null or char_length(email) <= 150),
  city          text check (city is null or char_length(city) <= 80),
  plan          text check (plan is null or plan in ('clinic', 'hospital', 'enterprise', 'custom', 'unsure')),
  message       text check (message is null or char_length(message) <= 2000),
  source        text check (source is null or char_length(source) <= 255),
  status        text not null default 'new' check (status in ('new', 'contacted', 'won', 'lost')),
  notes         text
);
create index if not exists platform_leads_created_idx on public.platform_leads (created_at desc);
alter table public.platform_leads enable row level security;
revoke all on public.platform_leads from anon, authenticated;
grant select, update, delete on public.platform_leads to authenticated;
grant all on public.platform_leads to service_role;
drop policy if exists platform_leads_admin on public.platform_leads;
create policy platform_leads_admin on public.platform_leads for all to authenticated
  using (public.provider_role() = 'admin') with check (public.provider_role() = 'admin');

create or replace function public.submit_platform_lead(
  p_name text, p_organisation text, p_phone text, p_email text default null, p_city text default null,
  p_plan text default null, p_message text default null, p_source text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_phone text := regexp_replace(coalesce(p_phone, ''), '[^0-9+]', '', 'g');
        v_email text := nullif(lower(trim(coalesce(p_email, ''))), '');
begin
  if char_length(trim(coalesce(p_name, ''))) < 2 then raise exception 'Please enter your name.'; end if;
  if char_length(trim(coalesce(p_organisation, ''))) < 2 then raise exception 'Please enter your hospital or clinic name.'; end if;
  if v_phone !~ '^\+?[0-9]{10,13}$' then raise exception 'Please enter a valid mobile number.'; end if;
  if v_email is not null and v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then raise exception 'Please enter a valid email or leave it empty.'; end if;
  -- spam guard: one request per number every 10 minutes, and a ceiling for the whole form
  if exists (select 1 from public.platform_leads where phone = v_phone and created_at > now() - interval '10 minutes') then
    return;   -- already received — quietly accept the repeat
  end if;
  if (select count(*) from public.platform_leads where created_at > now() - interval '1 hour') >= 60 then
    raise exception 'We are receiving a lot of requests right now. Please try again in a few minutes.';
  end if;
  insert into public.platform_leads (name, organisation, phone, email, city, plan, message, source)
  values (left(trim(p_name), 100), left(trim(p_organisation), 150), v_phone, left(v_email, 150), nullif(left(trim(coalesce(p_city, '')), 80), ''),
          case when p_plan in ('clinic', 'hospital', 'enterprise', 'custom', 'unsure') then p_plan end,
          nullif(left(trim(coalesce(p_message, '')), 2000), ''), left(p_source, 255));
end $$;
revoke all on function public.submit_platform_lead(text, text, text, text, text, text, text, text) from public;
grant execute on function public.submit_platform_lead(text, text, text, text, text, text, text, text) to anon, authenticated;

-- ------------------------------------------------------------------ Hospital Comrade messaging (phase 3)
-- Platform-wide settings, no tenant_id. 'messaging' = approved template / DLT IDs for the shared accounts:
--   { "templates": { "<event>": { "waTemplate": "…", "waParams": "name,date", "smsTemplateId": "…" } } }
-- (the shared accounts' credentials are Edge Function secrets — PLATFORM_* — never stored here).
-- Only Hospital Comrade admins read or change it; the notify function reads it with the service role.
create table if not exists public.platform_settings (
  key         text primary key,
  data        jsonb not null default '{}'::jsonb,
  updated_at  timestamptz not null default now(),
  updated_by  uuid
);
alter table public.platform_settings enable row level security;
revoke all on public.platform_settings from anon, authenticated;
grant select, insert, update on public.platform_settings to authenticated;
grant all on public.platform_settings to service_role;
drop policy if exists platform_settings_admin on public.platform_settings;
create policy platform_settings_admin on public.platform_settings for all to authenticated
  using (public.provider_role() = 'admin') with check (public.provider_role() = 'admin');
insert into public.platform_settings (key, data) values ('messaging', '{"templates": {}}'::jsonb) on conflict (key) do nothing;

-- record_message_usage(): see billing.sql (it also charges the wallet, phase 4)


-- =====================================================================================================
--  21. LICENCE, WALLET & PAYMENTS — Hospital Comrade phase 4 (loaded last: every hospital table exists)
-- =====================================================================================================
--  • Licence: tenants.trial_ends_at / paid_until → tenant_license() (tenancy_core.sql). In read_only (after the grace
--    period) and suspended hospitals nobody but the platform team can add or change anything: license_guard() runs on
--    every hospital table — also inside website RPCs such as online booking — while reading and signing in still work.
--  • Wallet: prepaid ₹ balance (tenants.wallet_paise) for messages on Hospital Comrade's shared accounts beyond the
--    plan's included messages. Every change is a row in wallet_ledger; usage is one row per day and channel.
--  • Payments: billing_payments (Razorpay orders from the `billing` Edge Function, or manual entries by the platform
--    team). apply_payment() is idempotent: renews the plan or tops up the wallet and numbers the tax invoice.
--  • Prices, GST, trial / grace days and message rates: platform_settings 'billing' (defaults from src/platform/billing.ts);
--    per-hospital overrides in tenants.billing (custom price, included messages, rates).

insert into public.platform_settings (key, data) values ('billing', $json${"currency":"INR","gstPercent":18,"trialDays":14,"graceDays":7,"yearlyMonths":10,"minTopup":500,"maxTopup":100000,"ratesPaise":{"sms":30,"whatsapp":40,"email":2},"plans":{"clinic":{"price":999,"included":{"sms":100,"whatsapp":300,"email":1000}},"hospital":{"price":2999,"included":{"sms":500,"whatsapp":1500,"email":5000}},"enterprise":{"price":7999,"included":{"sms":2000,"whatsapp":5000,"email":20000}},"custom":{"price":null,"included":{"sms":0,"whatsapp":0,"email":0}}},"seller":{"name":"Digital Comrade","gstin":"","address":"","state":"Bihar","email":"","sac":"998315"}}$json$::jsonb)
on conflict (key) do update set data = excluded.data || public.platform_settings.data;   -- new keys arrive, saved values win

create or replace function public.billing_config()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((select data from public.platform_settings where key = 'billing'), '{}'::jsonb)
$$;

-- ------------------------------------------------------------------ tables
create sequence if not exists public.billing_invoice_seq;

create table if not exists public.billing_payments (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null default public.current_tenant() references public.tenants (id) on delete cascade,
  created_at   timestamptz not null default now(),
  kind         text not null check (kind in ('plan', 'wallet')),
  plan         text,
  months       int check (months is null or months between 1 and 36),
  base_paise   bigint not null check (base_paise >= 0),
  gst_paise    bigint not null default 0 check (gst_paise >= 0),
  total_paise  bigint not null check (total_paise >= 0),
  status       text not null default 'created' check (status in ('created', 'paid', 'failed', 'refunded')),
  provider     text not null default 'razorpay' check (provider in ('razorpay', 'manual')),
  order_id     text unique,
  payment_id   text,
  method       text,
  paid_at      timestamptz,
  invoice_no   text unique,
  period_from  date,
  period_to    date,
  buyer        jsonb not null default '{}'::jsonb,       -- legal name / GSTIN / address at the time of payment
  note         text,
  created_by   uuid
);
-- phase 6: the seller printed on the tax invoice, as it was when the invoice was numbered (invoices never change later)
alter table public.billing_payments add column if not exists seller jsonb;
create index if not exists billing_payments_tenant_idx on public.billing_payments (tenant_id, created_at desc);

create table if not exists public.wallet_ledger (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null default public.current_tenant() references public.tenants (id) on delete cascade,
  created_at     timestamptz not null default now(),
  day            date not null default (now() at time zone 'Asia/Kolkata')::date,
  kind           text not null check (kind in ('topup', 'usage', 'refund', 'adjustment')),
  channel        text check (channel is null or channel in ('sms', 'whatsapp', 'email')),
  units          int not null default 0,
  amount_paise   bigint not null,                        -- + credit, − debit
  balance_paise  bigint not null,                        -- balance after this row
  payment        uuid references public.billing_payments (id) on delete set null,
  note           text,
  created_by     uuid
);
create index if not exists wallet_ledger_tenant_idx on public.wallet_ledger (tenant_id, created_at desc);
create unique index if not exists wallet_ledger_usage_day on public.wallet_ledger (tenant_id, day, channel) where kind = 'usage';

-- read: the hospital's owner and accountant (and the platform team working as them); writes only through the functions
do $rls$
declare t text;
begin
  foreach t in array array['billing_payments', 'wallet_ledger'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
    execute format('grant all on public.%I to service_role', t);
    execute format('drop policy if exists tenant_isolation on public.%I', t);
    execute format('create policy tenant_isolation on public.%I as restrictive for all to anon, authenticated
                      using (tenant_id = (select public.current_tenant())) with check (tenant_id = (select public.current_tenant()))', t);
    execute format('drop policy if exists billing_read on public.%I', t);
    execute format('create policy billing_read on public.%I for select to authenticated using (public.has_role(''owner'', ''accountant''))', t);
    execute format('drop trigger if exists trg_keep_tenant on public.%I', t);
    execute format('create trigger trg_keep_tenant before update of tenant_id on public.%I for each row execute function public.keep_tenant()', t);
  end loop;
end $rls$;

-- the wallet balance and billing overrides are not for visitors or staff (tenants is readable by anon for the website):
-- every other column stays readable, these two only through billing_summary() / my_context()
do $cols$
declare v_cols text;
begin
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into v_cols
    from information_schema.columns where table_schema = 'public' and table_name = 'tenants' and column_name not in ('wallet_paise', 'billing');
  execute 'revoke select on public.tenants from anon, authenticated';
  execute format('grant select (%s) on public.tenants to anon, authenticated', v_cols);
end $cols$;

-- ------------------------------------------------------------------ licence guard
-- Raised for API callers (anon / authenticated — also inside SECURITY DEFINER RPCs, where `role` still names the
-- caller) in read_only / suspended hospitals. The platform team (admin / finance), the service role (Edge Functions)
-- and the database itself are never blocked.
create or replace function public.license_guard()
returns trigger language plpgsql set search_path = public as $$
declare v_tenant uuid; v_state text;
begin
  if coalesce(current_setting('role', true), '') not in ('anon', 'authenticated') then return coalesce(new, old); end if;
  if public.provider_role() in ('admin', 'finance') then return coalesce(new, old); end if;
  v_tenant := case when tg_op = 'DELETE' then old.tenant_id else new.tenant_id end;
  v_state := public.tenant_license(v_tenant);
  if v_state in ('read_only', 'suspended') then
    raise exception 'LICENSE_READ_ONLY: This hospital''s Hospital Comrade plan has ended, so the account is read-only. The owner can renew it in Settings → Plan & billing.'
      using errcode = '42501';
  end if;
  return coalesce(new, old);
end $$;

-- every hospital table except the ones that must keep working while read-only (sign-in, password reset, devices,
-- delivery bookkeeping, logs and billing itself)
do $guard$
declare t text;
begin
  for t in select c.table_name from information_schema.columns c
            join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name and x.table_type = 'BASE TABLE'
           where c.table_schema = 'public' and c.column_name = 'tenant_id'
             and c.table_name not in ('tenant_domains', 'provider_assignments', 'provider_audit', 'profiles', 'push_tokens', 'password_reset_otps',
                                      'notification_outbox', 'message_usage', 'audit_log', 'billing_payments', 'wallet_ledger')
  loop
    execute format('drop trigger if exists trg_license_guard on public.%I', t);
    execute format('create trigger trg_license_guard before insert or update or delete on public.%I for each row execute function public.license_guard()', t);
  end loop;
end $guard$;

-- ------------------------------------------------------------------ wallet
create or replace function public.wallet_apply(p_tenant uuid, p_kind text, p_amount bigint, p_payment uuid default null,
  p_note text default null, p_channel text default null, p_units int default 0)
returns bigint language plpgsql volatile security definer set search_path = public as $$
declare v_bal bigint; v_day date := (now() at time zone 'Asia/Kolkata')::date;
begin
  update public.tenants set wallet_paise = wallet_paise + p_amount where id = p_tenant returning wallet_paise into v_bal;
  if not found then raise exception 'No hospital with id %', p_tenant; end if;
  if p_kind = 'usage' then   -- one row per day and channel
    insert into public.wallet_ledger (tenant_id, day, kind, channel, units, amount_paise, balance_paise)
    values (p_tenant, v_day, 'usage', p_channel, p_units, p_amount, v_bal)
    on conflict (tenant_id, day, channel) where kind = 'usage' do update
      set units = public.wallet_ledger.units + excluded.units, amount_paise = public.wallet_ledger.amount_paise + excluded.amount_paise,
          balance_paise = excluded.balance_paise, created_at = now();
  else
    insert into public.wallet_ledger (tenant_id, day, kind, channel, units, amount_paise, balance_paise, payment, note, created_by)
    values (p_tenant, v_day, p_kind, p_channel, coalesce(p_units, 0), p_amount, v_bal, p_payment, p_note, auth.uid());
  end if;
  return v_bal;
end $$;

-- the notify function adds each batch's outcome (service role only). Messages on the shared accounts beyond the
-- plan's included messages this month are charged to the wallet (the primary hospital is never charged).
create or replace function public.record_message_usage(p_tenant uuid, p_channel text, p_source text, p_sent int, p_failed int)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  v_month  date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
  v_src    text := coalesce(p_source, 'own');
  v_before int;
  v_inc    int;
  v_rate   int;
  v_units  int;
  t        public.tenants;
  cfg      jsonb := public.billing_config();
begin
  if coalesce(p_sent, 0) = 0 and coalesce(p_failed, 0) = 0 then return; end if;
  select sent into v_before from public.message_usage
   where tenant_id = p_tenant and month = v_month and channel = p_channel and source = v_src for update;
  insert into public.message_usage (tenant_id, month, channel, source, sent, failed)
  values (p_tenant, v_month, p_channel, v_src, greatest(coalesce(p_sent, 0), 0), greatest(coalesce(p_failed, 0), 0))
  on conflict (tenant_id, month, channel, source) do update
    set sent = public.message_usage.sent + excluded.sent, failed = public.message_usage.failed + excluded.failed, updated_at = now();
  if v_src <> 'platform' or coalesce(p_sent, 0) <= 0 or p_channel not in ('sms', 'whatsapp', 'email') then return; end if;
  select * into t from public.tenants where id = p_tenant;
  if not found or t.is_primary then return; end if;
  v_inc  := coalesce((t.billing -> 'included' ->> p_channel)::int, (cfg -> 'plans' -> t.plan -> 'included' ->> p_channel)::int, 0);
  v_rate := coalesce((t.billing -> 'ratesPaise' ->> p_channel)::int, (cfg -> 'ratesPaise' ->> p_channel)::int, 0);
  v_before := coalesce(v_before, 0);
  v_units := greatest(0, v_before + p_sent - greatest(v_inc, v_before));
  if v_units > 0 and v_rate > 0 then
    perform public.wallet_apply(p_tenant, 'usage', -(v_units::bigint * v_rate), null, null, p_channel, v_units);
  end if;
end $$;

-- ------------------------------------------------------------------ prices
-- What a plan renewal (1 or 12 months) or a wallet top-up (₹) costs this hospital, GST included.
-- p_plan (phase 6): renew on another plan — it switches when the payment arrives (custom-priced hospitals: ask the team)
drop function if exists public.billing_quote(uuid, text, int, numeric);
create or replace function public.billing_quote(p_tenant uuid, p_kind text, p_months int default 1, p_amount numeric default null, p_plan text default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  t      public.tenants;
  v_plan text;
  cfg    jsonb := public.billing_config();
  v_gst  numeric := coalesce((cfg ->> 'gstPercent')::numeric, 18);
  v_price numeric;
  v_base bigint;
  v_from date;
  v_today date := (now() at time zone 'Asia/Kolkata')::date;
begin
  select * into t from public.tenants where id = p_tenant;
  if not found then raise exception 'No hospital selected'; end if;
  if p_kind = 'plan' then
    if coalesce(p_months, 0) not in (1, 12) then raise exception 'Choose 1 month or 12 months.'; end if;
    v_plan := coalesce(nullif(p_plan, ''), t.plan);
    if v_plan <> t.plan then
      if not (cfg -> 'plans' ? v_plan) then raise exception 'Unknown plan %', v_plan; end if;
      if (t.billing ->> 'price') is not null then
        raise exception 'Your price was agreed with Hospital Comrade — ask them to change your plan.';
      end if;
    end if;
    v_price := case when v_plan = t.plan then coalesce((t.billing ->> 'price')::numeric, (cfg -> 'plans' -> t.plan ->> 'price')::numeric)
                    else (cfg -> 'plans' -> v_plan ->> 'price')::numeric end;
    if v_price is null or v_price <= 0 then
      raise exception 'Your plan is priced individually — Hospital Comrade will send you the payment details.';
    end if;
    v_base := round(v_price * 100 * case when p_months = 12 then coalesce((cfg ->> 'yearlyMonths')::int, 12) else 1 end);
    -- the new period starts after whatever is already paid (or the trial), never in the past
    v_from := greatest(v_today, (greatest(coalesce(t.paid_until, '-infinity'::timestamptz), coalesce(t.trial_ends_at, '-infinity'::timestamptz)) at time zone 'Asia/Kolkata')::date);
    return jsonb_build_object('kind', 'plan', 'plan', v_plan, 'months', p_months, 'base_paise', v_base,
      'gst_paise', round(v_base * v_gst / 100)::bigint, 'total_paise', v_base + round(v_base * v_gst / 100)::bigint, 'gst_percent', v_gst,
      'period_from', v_from, 'period_to', (v_from + make_interval(months => p_months) - interval '1 day')::date);
  elsif p_kind = 'wallet' then
    if p_amount is null or p_amount < coalesce((cfg ->> 'minTopup')::numeric, 500) or p_amount > coalesce((cfg ->> 'maxTopup')::numeric, 100000) then
      raise exception 'Top up between ₹% and ₹%.', coalesce(cfg ->> 'minTopup', '500'), coalesce(cfg ->> 'maxTopup', '100000');
    end if;
    v_base := round(p_amount * 100);
    return jsonb_build_object('kind', 'wallet', 'months', null, 'base_paise', v_base, 'gst_paise', round(v_base * v_gst / 100)::bigint,
      'total_paise', v_base + round(v_base * v_gst / 100)::bigint, 'gst_percent', v_gst);
  end if;
  raise exception 'Unknown payment type';
end $$;

-- ------------------------------------------------------------------ payments
-- Marks a payment paid (once — repeats are ignored), numbers the tax invoice (HC/2026-27/000001, Indian financial
-- year) and applies it: a plan renewal extends paid_until by its months, a top-up credits the wallet (GST excluded).
create or replace function public.apply_payment(p_payment uuid, p_ref text default null, p_method text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  p      public.billing_payments;
  v_d    date := (now() at time zone 'Asia/Kolkata')::date;
  v_fy   text;
  v_inv  text;
  t      public.tenants;
begin
  select * into p from public.billing_payments where id = p_payment for update;
  if not found then raise exception 'Payment not found'; end if;
  if p.status = 'paid' then return jsonb_build_object('ok', true, 'already', true, 'invoice_no', p.invoice_no); end if;
  v_fy := case when extract(month from v_d) >= 4 then to_char(v_d, 'YYYY') || '-' || to_char(v_d + interval '1 year', 'YY')
               else to_char(v_d - interval '1 year', 'YYYY') || '-' || to_char(v_d, 'YY') end;
  v_inv := 'HC/' || v_fy || '/' || lpad(nextval('public.billing_invoice_seq')::text, 6, '0');
  select * into t from public.tenants where id = p.tenant_id for update;
  update public.billing_payments set status = 'paid', paid_at = now(), invoice_no = v_inv,
         payment_id = coalesce(p_ref, payment_id), method = coalesce(p_method, method),
         seller = coalesce(seller, public.billing_config() -> 'seller'),
         buyer = case when buyer = '{}'::jsonb then jsonb_build_object('name', coalesce(t.billing ->> 'legalName', t.name), 'gstin', coalesce(t.billing ->> 'gstin', ''),
                                                                       'address', coalesce(t.billing ->> 'address', '')) else buyer end
   where id = p.id;
  if p.kind = 'plan' then
    update public.tenants
       set plan = coalesce(p.plan, plan),
           paid_until = greatest(now(), coalesce(paid_until, now()), coalesce(trial_ends_at, now())) + make_interval(months => coalesce(p.months, 1)),
           status = case when status = 'suspended' then status else 'active' end
     where id = p.tenant_id;
  else
    perform public.wallet_apply(p.tenant_id, 'topup', p.base_paise, p.id, 'Wallet top-up · ' || v_inv);
  end if;
  return jsonb_build_object('ok', true, 'already', false, 'invoice_no', v_inv);
end $$;

-- ------------------------------------------------------------------ for the app (owner / accountant / platform team)
create or replace function public.billing_summary()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  t      public.tenants;
  cfg    jsonb := public.billing_config();
  v_month date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
begin
  if not public.has_role('owner', 'accountant') then raise exception 'Only the owner or accountant can see billing.' using errcode = '42501'; end if;
  select * into t from public.tenants where id = public.current_tenant();
  if not found then return null; end if;
  return jsonb_build_object(
    'license', public.tenant_license_dates(t.id), 'is_primary', t.is_primary,
    'plan', t.plan,
    'price', coalesce((t.billing ->> 'price')::numeric, (cfg -> 'plans' -> t.plan ->> 'price')::numeric),
    'included', coalesce(cfg -> 'plans' -> t.plan -> 'included', '{}'::jsonb) || coalesce(t.billing -> 'included', '{}'::jsonb),
    'rates_paise', coalesce(cfg -> 'ratesPaise', '{}'::jsonb) || coalesce(t.billing -> 'ratesPaise', '{}'::jsonb),
    'wallet_paise', t.wallet_paise,
    'gst_percent', coalesce((cfg ->> 'gstPercent')::numeric, 18), 'yearly_months', coalesce((cfg ->> 'yearlyMonths')::int, 12),
    'min_topup', coalesce((cfg ->> 'minTopup')::numeric, 500), 'max_topup', coalesce((cfg ->> 'maxTopup')::numeric, 100000),
    'buyer', jsonb_build_object('legalName', coalesce(t.billing ->> 'legalName', t.name), 'gstin', coalesce(t.billing ->> 'gstin', ''), 'address', coalesce(t.billing ->> 'address', '')),
    -- phase 6: plan picker + invoices
    'custom_price', (t.billing ->> 'price') is not null,
    'plans', coalesce((select jsonb_object_agg(e.key, jsonb_build_object('price', e.value -> 'price', 'included', e.value -> 'included')) from jsonb_each(cfg -> 'plans') e), '{}'::jsonb),
    'seller', coalesce(cfg -> 'seller', '{}'::jsonb),
    'usage', coalesce((select jsonb_object_agg(channel, sent) from public.message_usage where tenant_id = t.id and month = v_month and source = 'platform'), '{}'::jsonb));
end $$;

drop function if exists public.my_billing_quote(text, int, numeric);
create or replace function public.my_billing_quote(p_kind text, p_months int default 1, p_amount numeric default null, p_plan text default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_role('owner', 'accountant') then raise exception 'Only the owner or accountant can see prices.' using errcode = '42501'; end if;
  return public.billing_quote(public.current_tenant(), p_kind, p_months, p_amount, p_plan);
end $$;

-- phase 6: during the free trial (nothing paid yet) the owner may try another plan straight away
create or replace function public.change_trial_plan(p_plan text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants; cfg jsonb := public.billing_config();
begin
  if not public.has_role('owner') then raise exception 'Only the owner can change the plan.' using errcode = '42501'; end if;
  select * into t from public.tenants where id = public.current_tenant() for update;
  if not found or t.is_primary then raise exception 'No plan to change here.'; end if;
  if not (cfg -> 'plans' ? coalesce(p_plan, '')) then raise exception 'Unknown plan %', p_plan; end if;
  if (cfg -> 'plans' -> p_plan ->> 'price') is null then raise exception 'That plan is priced individually — Hospital Comrade will get in touch.'; end if;
  if (t.billing ->> 'price') is not null then raise exception 'Your price was agreed with Hospital Comrade — ask them to change your plan.'; end if;
  if public.tenant_license(t.id) <> 'trial' or coalesce(t.paid_until > now(), false) then
    raise exception 'Your plan is paid — choose the new plan when you renew; it switches when the payment arrives.';
  end if;
  update public.tenants set plan = p_plan, updated_at = now() where id = t.id;
  return public.billing_summary();
end $$;

-- phase 6: messages per month on the shared accounts (sent, included, charged to the wallet) — the usage chart
create or replace function public.billing_usage_history(p_months int default 6)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_t   uuid := public.current_tenant();
  v_now date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
  v_n   int := least(greatest(coalesce(p_months, 6), 1), 24);
begin
  if not public.has_role('owner', 'accountant') then raise exception 'Only the owner or accountant can see billing.' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'month', to_char(m.month, 'YYYY-MM'),
      'sent', coalesce((select jsonb_object_agg(u.channel, u.sent) from public.message_usage u where u.tenant_id = v_t and u.month = m.month and u.source = 'platform' and u.channel <> 'push'), '{}'::jsonb),
      'own', coalesce((select sum(u.sent) from public.message_usage u where u.tenant_id = v_t and u.month = m.month and u.source = 'own'), 0),
      'charged_paise', coalesce((select -sum(l.amount_paise) from public.wallet_ledger l where l.tenant_id = v_t and l.kind = 'usage'
                                   and date_trunc('month', l.day)::date = m.month), 0)) order by m.month)
    from (select (v_now - make_interval(months => g))::date as month from generate_series(v_n - 1, 0, -1) g) m), '[]'::jsonb);
end $$;

-- phase 6: renewal reminders to each hospital's owner — 7, 3 and 1 day before the trial / plan ends, and once when the
-- grace period starts. E-mail (+ app push). Daily from the scheduler (Settings → Notifications → automatic delivery).
create or replace function public.queue_billing_reminders()
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  r       record;
  v_count int := 0;
  v_today date := (now() at time zone 'Asia/Kolkata')::date;
  v_left  int;
  v_m     text;
  v_end   timestamptz;
  v_name  text;
  v_mail  text;
  v_prof  uuid;
  v_subj  text;
  v_body  text;
  v_link  text;
  cfg     jsonb := public.billing_config();
begin
  if auth.uid() is not null and coalesce(public.provider_role(), '') <> 'admin' then raise exception 'Not allowed' using errcode = '42501'; end if;
  for r in select t.*, public.tenant_license(t.id) as lic from public.tenants t where not t.is_primary and t.status <> 'suspended' loop
    v_end := greatest(coalesce(r.paid_until, '-infinity'::timestamptz), coalesce(r.trial_ends_at, '-infinity'::timestamptz));
    continue when v_end = '-infinity'::timestamptz;
    v_left := ((v_end at time zone 'Asia/Kolkata')::date - v_today);
    v_m := case when r.lic in ('trial', 'active') and v_left in (7, 3, 1) then 'd' || v_left
                when r.lic = 'grace' then 'grace' end;
    continue when v_m is null;
    -- once per hospital, milestone and end date (paying moves the end date, so the next round starts fresh)
    continue when exists (select 1 from public.notification_outbox o where o.tenant_id = r.id and o.event = 'billing_reminder'
                            and o.vars ->> 'milestone' = v_m and o.vars ->> 'until' = to_char(v_end at time zone 'Asia/Kolkata', 'YYYY-MM-DD'));
    select p.id, p.full_name, p.email into v_prof, v_name, v_mail from public.profiles p where p.tenant_id = r.id and p.role = 'owner' order by p.created_at limit 1;
    v_mail := coalesce(v_mail, (select s.data ->> 'owner_email' from public.app_settings s where s.tenant_id = r.id and s.key = 'bootstrap'));
    continue when v_mail is null and v_prof is null;
    v_link := coalesce((select 'https://' || d.domain || '/billing' from public.tenant_domains d where d.tenant_id = r.id order by d.is_primary desc, (d.verified_at is null), d.created_at limit 1),
                       nullif(rtrim(coalesce((select c.data ->> 'siteUrl' from public.site_content c where c.tenant_id = r.id and c.key = 'settings'), ''), '/') || '/billing', '/billing'),
                       'the app → Billing & plan');
    v_subj := case when v_m = 'grace' then '{hospital}: renew now to keep adding records'
                   when r.lic = 'trial' then '{hospital}: your free trial ends {date}'
                   else '{hospital}: your plan renews {date}' end;
    v_body := case when v_m = 'grace'
      then 'Namaste {name}, the {plan} plan for {hospital} has ended. Everything still works until {read_only}; after that the app becomes read-only until you renew. Renew in a minute: {link}'
      else 'Namaste {name}, the ' || case when r.lic = 'trial' then 'free trial' else '{plan} plan' end
           || ' for {hospital} ends on {date} ({days}). Renew in a minute: {link} — UPI, cards and net banking, with a GST invoice.' end;
    perform set_config('app.tenant_id', r.id::text, true);
    v_count := v_count + public.notify_enqueue_raw('billing_reminder',
      jsonb_build_object('subject', v_subj, 'text', v_body), array['email', 'push'], null, v_mail, v_prof,
      jsonb_build_object('name', split_part(coalesce(v_name, 'there'), ' ', 1), 'milestone', v_m,
        'hospital', coalesce(nullif((select c.data ->> 'name' from public.site_content c where c.tenant_id = r.id and c.key = 'settings'), ''), r.name),
        'until', to_char(v_end at time zone 'Asia/Kolkata', 'YYYY-MM-DD'), 'date', to_char(v_end at time zone 'Asia/Kolkata', 'DD Mon YYYY'),
        'days', case when v_left = 1 then 'tomorrow' else 'in ' || v_left || ' days' end,
        'read_only', to_char((v_end + make_interval(days => coalesce((cfg ->> 'graceDays')::int, 7))) at time zone 'Asia/Kolkata', 'DD Mon YYYY'),
        'plan', initcap(r.plan), 'link', v_link),
      'tenants', r.id, null);
  end loop;
  perform set_config('app.tenant_id', '', true);
  return v_count;
end $$;

-- the owner keeps the name and GSTIN printed on Hospital Comrade's invoices up to date
create or replace function public.set_billing_details(p_legal_name text, p_gstin text, p_address text)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_gstin text := upper(regexp_replace(coalesce(p_gstin, ''), '\s', '', 'g'));
begin
  if not public.has_role('owner') then raise exception 'Only the owner can change billing details.' using errcode = '42501'; end if;
  if v_gstin <> '' and v_gstin !~ '^[0-9]{2}[A-Z0-9]{10}[0-9A-Z]Z[0-9A-Z]$' then raise exception 'That GSTIN does not look right (15 characters, e.g. 10ABCDE1234F1Z5).'; end if;
  update public.tenants set billing = billing || jsonb_build_object('legalName', left(trim(coalesce(p_legal_name, '')), 150), 'gstin', v_gstin, 'address', left(trim(coalesce(p_address, '')), 300))
   where id = public.current_tenant();
end $$;

-- ------------------------------------------------------------------ platform team tools (until the provider panel)
-- Works on the hospital chosen in the provider banner. admin: everything; finance: manual payments + wallet adjustments.
--   manual_payment  { kind: plan|wallet, months?, amount?, method: bank|upi|cash|cheque, reference?, note? }
--   wallet_adjust   { amount: ±₹, note }            extend_trial { days }            (admin)
--   set_plan        { plan?, price?, included?, ratesPaise? }  (admin; price null = plan price)
--   suspend / resume                                          (admin)
create or replace function public.provider_billing(p_action text, p_args jsonb default '{}'::jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_mode   text := public.provider_mode();
  v_tenant uuid := public.current_tenant();
  q        jsonb;
  v_id     uuid;
  r        jsonb;
  v_amt    numeric;
  cfg      jsonb := public.billing_config();
begin
  if v_mode not in ('admin', 'finance') or not public.provider_can(v_tenant) then
    raise exception 'Only Hospital Comrade admins or finance can do this.' using errcode = '42501';
  end if;
  if p_action in ('extend_trial', 'set_plan', 'suspend', 'resume') and v_mode <> 'admin' then
    raise exception 'Only a Hospital Comrade admin can do this.' using errcode = '42501';
  end if;
  if p_action = 'manual_payment' then
    q := public.billing_quote(v_tenant, p_args ->> 'kind', coalesce((p_args ->> 'months')::int, 1), (p_args ->> 'amount')::numeric, p_args ->> 'plan');
    insert into public.billing_payments (tenant_id, kind, plan, months, base_paise, gst_paise, total_paise, provider, method, payment_id, note,
                                         period_from, period_to, created_by)
    values (v_tenant, q ->> 'kind', q ->> 'plan', (q ->> 'months')::int, (q ->> 'base_paise')::bigint, (q ->> 'gst_paise')::bigint, (q ->> 'total_paise')::bigint,
            'manual', coalesce(nullif(p_args ->> 'method', ''), 'bank'), nullif(p_args ->> 'reference', ''), nullif(p_args ->> 'note', ''),
            (q ->> 'period_from')::date, (q ->> 'period_to')::date, auth.uid())
    returning id into v_id;
    r := public.apply_payment(v_id);
  elsif p_action = 'wallet_adjust' then
    v_amt := (p_args ->> 'amount')::numeric;
    if v_amt is null or v_amt = 0 or abs(v_amt) > 100000 then raise exception 'Enter an amount between -₹1,00,000 and ₹1,00,000.'; end if;
    if coalesce(trim(p_args ->> 'note'), '') = '' then raise exception 'Add a note saying why.'; end if;
    r := jsonb_build_object('wallet_paise', public.wallet_apply(v_tenant, 'adjustment', round(v_amt * 100)::bigint, null, left(p_args ->> 'note', 200)));
  elsif p_action = 'extend_trial' then
    if coalesce((p_args ->> 'days')::int, 0) not between 1 and 90 then raise exception 'Extend by 1 to 90 days.'; end if;
    update public.tenants set trial_ends_at = greatest(now(), coalesce(trial_ends_at, now())) + make_interval(days => (p_args ->> 'days')::int),
                              status = case when status in ('suspended', 'active') then status else 'trial' end
     where id = v_tenant;
  elsif p_action = 'set_plan' then
    if p_args ? 'plan' and not (cfg -> 'plans' ? (p_args ->> 'plan')) then raise exception 'Unknown plan'; end if;
    update public.tenants
       set plan = coalesce(p_args ->> 'plan', plan),
           billing = (billing - 'price' - 'included' - 'ratesPaise')
                     || case when p_args ? 'price' and p_args -> 'price' <> 'null'::jsonb then jsonb_build_object('price', (p_args ->> 'price')::numeric)
                             when not (p_args ? 'price') and billing ? 'price' then jsonb_build_object('price', billing -> 'price') else '{}'::jsonb end
                     || case when p_args ? 'included' then jsonb_build_object('included', p_args -> 'included')
                             when billing ? 'included' then jsonb_build_object('included', billing -> 'included') else '{}'::jsonb end
                     || case when p_args ? 'ratesPaise' then jsonb_build_object('ratesPaise', p_args -> 'ratesPaise')
                             when billing ? 'ratesPaise' then jsonb_build_object('ratesPaise', billing -> 'ratesPaise') else '{}'::jsonb end
     where id = v_tenant;
  elsif p_action = 'suspend' then
    update public.tenants set status = 'suspended' where id = v_tenant and not is_primary;
  elsif p_action = 'resume' then
    update public.tenants set status = case when paid_until > now() then 'active' when trial_ends_at > now() then 'trial' else 'active' end
     where id = v_tenant and status = 'suspended';
  else
    raise exception 'Unknown action %', p_action;
  end if;
  perform public.provider_log('billing:' || p_action, v_tenant::text, p_args);
  return coalesce(r, '{}'::jsonb) || jsonb_build_object('license', public.tenant_license_dates(v_tenant));
end $$;

-- ------------------------------------------------------------------ who may call what
revoke all on function public.billing_config(), public.license_guard(), public.wallet_apply(uuid, text, bigint, uuid, text, text, int),
  public.record_message_usage(uuid, text, text, int, int), public.billing_quote(uuid, text, int, numeric, text),
  public.apply_payment(uuid, text, text), public.queue_billing_reminders() from public, anon, authenticated;
grant execute on function public.record_message_usage(uuid, text, text, int, int), public.billing_quote(uuid, text, int, numeric, text),
  public.apply_payment(uuid, text, text), public.queue_billing_reminders() to service_role;
revoke all on function public.billing_summary(), public.my_billing_quote(text, int, numeric, text), public.set_billing_details(text, text, text),
  public.provider_billing(text, jsonb), public.change_trial_plan(text), public.billing_usage_history(int) from public, anon;
grant execute on function public.billing_summary(), public.my_billing_quote(text, int, numeric, text), public.set_billing_details(text, text, text),
  public.provider_billing(text, jsonb), public.change_trial_plan(text), public.billing_usage_history(int) to authenticated;
grant execute on function public.tenant_license(uuid), public.tenant_license_dates(uuid) to anon, authenticated, service_role;


-- =====================================================================================================
--  22. HOSPITAL COMRADE CONTROL PANEL — phase 5 (the separate /control-panel/ app; loaded after billing.sql)
-- =====================================================================================================
--  Every function checks the caller itself (SECURITY DEFINER, explicit provider checks):
--    admin   — every hospital; create / edit hospitals, team, platform settings, audit
--    finance — assigned hospitals; billing actions (manual payments, wallet) and payments
--    support — assigned hospitals; read-only here
--  Acting on one hospital reuses the hospital-scoped functions (provider_billing) with that hospital pinned in the
--  transaction (app.tenant_id), so the same rules and the same provider audit apply.

create or replace function public.cp_require(p_roles text[] default array['admin', 'support', 'finance'])
returns text language plpgsql stable security definer set search_path = public as $$
declare r text := public.provider_role();
begin
  if r is null or not (r = any (p_roles)) then
    raise exception 'Only the Hospital Comrade team (%) can do this.', array_to_string(p_roles, ' / ') using errcode = '42501';
  end if;
  return r;
end $$;

-- who is signed in to the panel (null = not a platform team member)
create or replace function public.cp_me()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('user_id', u.user_id, 'role', u.role, 'email', a.email, 'full_name', coalesce(p.full_name, split_part(a.email, '@', 1)))
    from public.provider_users u join auth.users a on a.id = u.user_id left join public.profiles p on p.id = u.user_id
   where u.user_id = auth.uid() and u.active
$$;

-- ------------------------------------------------------------------ hospitals
create or replace function public.cp_hospitals(p_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  cfg     jsonb := public.billing_config();
  v_month date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
  r       jsonb;
begin
  perform public.cp_require();
  select coalesce(jsonb_agg(h order by h ->> 'is_primary' desc, h ->> 'name'), '[]'::jsonb) into r from (
    select jsonb_build_object(
      'id', t.id, 'slug', t.slug, 'name', t.name, 'code', t.code, 'plan', t.plan, 'is_primary', t.is_primary, 'notes', t.notes,
      'created_at', t.created_at, 'modules', t.modules, 'license', public.tenant_license_dates(t.id), 'wallet_paise', t.wallet_paise,
      'price', coalesce((t.billing ->> 'price')::numeric, (cfg -> 'plans' -> t.plan ->> 'price')::numeric), 'billing', t.billing,
      'domain', (select d.domain from public.tenant_domains d where d.tenant_id = t.id order by d.is_primary desc, d.created_at limit 1),
      'staff', (select count(*) from public.profiles p where p.tenant_id = t.id and p.role <> 'patient'),
      'patients', (select count(*) from public.patients x where x.tenant_id = t.id),
      'owner_joined', exists (select 1 from public.profiles p where p.tenant_id = t.id and p.role = 'owner'),
      'owner_email', coalesce((select p.email from public.profiles p where p.tenant_id = t.id and p.role = 'owner' order by p.created_at limit 1),
                              (select s.data ->> 'owner_email' from public.app_settings s where s.tenant_id = t.id and s.key = 'bootstrap')),
      'messages', (select coalesce(sum(m.sent), 0) from public.message_usage m where m.tenant_id = t.id and m.month = v_month)
    ) h
    from public.tenants t
    where public.provider_can(t.id) and (p_id is null or t.id = p_id)
  ) q;
  return r;
end $$;

-- one hospital with its domains, team, payments and this month's messages
create or replace function public.cp_hospital(p_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  h       jsonb;
  v_role  text := public.cp_require();
  v_month date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
begin
  h := public.cp_hospitals(p_id) -> 0;
  if h is null then raise exception 'Hospital not found or not assigned to you.'; end if;
  return h || jsonb_build_object(
    'domains', coalesce((select jsonb_agg(jsonb_build_object('domain', d.domain, 'is_primary', d.is_primary, 'method', d.method, 'status', d.status, 'ssl_status', d.ssl_status, 'verified_at', d.verified_at)
                                          order by d.is_primary desc, d.created_at) from public.tenant_domains d where d.tenant_id = p_id), '[]'::jsonb),
    'team', coalesce((select jsonb_agg(jsonb_build_object('user_id', u.user_id, 'role', u.role, 'name', coalesce(p.full_name, a.email)) order by u.role)
                        from public.provider_users u join auth.users a on a.id = u.user_id left join public.profiles p on p.id = u.user_id
                       where u.active and (u.role = 'admin' or exists (select 1 from public.provider_assignments x where x.user_id = u.user_id and x.tenant_id = p_id))), '[]'::jsonb),
    'usage', coalesce((select jsonb_object_agg(m.channel || ':' || m.source, m.sent) from public.message_usage m where m.tenant_id = p_id and m.month = v_month), '{}'::jsonb),
    'payments', case when v_role = 'support' then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(b) - 'tenant_id' - 'buyer' order by b.created_at desc)
                  from (select * from public.billing_payments where tenant_id = p_id and status <> 'created' order by created_at desc limit 20) b), '[]'::jsonb) end);
end $$;

-- a new hospital: tenants row, address, owner e-mail (first sign-up with it becomes the owner), default settings
--   { slug, name, code, plan, owner_email, domain?, status: trial|active, trial_days?, months? (active), modules?, notes? }
create or replace function public.cp_create_hospital(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  cfg     jsonb := public.billing_config();
  v_slug  text := lower(trim(coalesce(p ->> 'slug', '')));
  v_name  text := trim(coalesce(p ->> 'name', ''));
  v_code  text := upper(trim(coalesce(p ->> 'code', '')));
  v_plan  text := coalesce(nullif(p ->> 'plan', ''), 'clinic');
  v_owner text := lower(trim(coalesce(p ->> 'owner_email', '')));
  v_dom   text := lower(trim(regexp_replace(coalesce(p ->> 'domain', ''), '^https?://|/.*$', '', 'g')));
  v_stat  text := coalesce(nullif(p ->> 'status', ''), 'trial');
  v_days  int := coalesce((p ->> 'trial_days')::int, (cfg ->> 'trialDays')::int, 14);
  v_mod   jsonb := coalesce(p -> 'modules', '{"dashboard": "hospital", "forms": "hospital", "notifications": "hospital", "security": "hospital"}'::jsonb);
  v_id    uuid;
begin
  perform public.cp_require(array['admin']);
  if v_slug !~ '^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$' then raise exception 'Short name: 2–40 characters, a-z, 0-9 and -, e.g. citycare'; end if;
  if char_length(v_name) not between 2 and 120 then raise exception 'Enter the hospital''s name.'; end if;
  if v_code !~ '^[A-Z]{2,6}$' then raise exception 'Record prefix: 2–6 capital letters, e.g. CCC'; end if;
  if not (cfg -> 'plans' ? v_plan) then raise exception 'Unknown plan %', v_plan; end if;
  if v_owner !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Enter the owner''s e-mail.'; end if;
  if v_stat not in ('trial', 'active') then raise exception 'Start as trial or active.'; end if;
  if v_days not between 1 and 90 then raise exception 'Trial: 1 to 90 days.'; end if;
  if v_dom <> '' and v_dom !~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$' then raise exception 'That address does not look like a domain (e.g. citycareclinic.in).'; end if;
  if exists (select 1 from public.tenants where slug = v_slug) then raise exception 'The short name % is taken.', v_slug; end if;
  if v_dom <> '' and exists (select 1 from public.tenant_domains where domain = v_dom) then raise exception '% already belongs to a hospital.', v_dom; end if;
  if exists (select 1 from public.profiles where lower(email) = v_owner and tenant_id is not null and role <> 'patient')
     or exists (select 1 from public.provider_users u join auth.users a on a.id = u.user_id where lower(a.email) = v_owner) then
    raise exception '% is already used by another hospital or the platform team — one account = one hospital, please use another e-mail.', v_owner;
  end if;
  if exists (select 1 from jsonb_each_text(v_mod) m where m.key not in ('general', 'appearance', 'dashboard', 'notifications', 'forms', 'security', 'data', 'cms')
                                                         or m.value not in ('hospital', 'provider')) then
    raise exception 'Unknown module setting';
  end if;

  insert into public.tenants (slug, name, code, plan, status, modules, notes, trial_ends_at, paid_until)
  values (v_slug, v_name, v_code, v_plan, v_stat, v_mod, nullif(trim(coalesce(p ->> 'notes', '')), ''),
          case when v_stat = 'trial' then now() + make_interval(days => v_days) end,
          case when v_stat = 'active' then now() + make_interval(months => greatest(1, least(36, coalesce((p ->> 'months')::int, 12)))) end)
  returning id into v_id;
  perform set_config('app.tenant_id', v_id::text, true);   -- everything below (and its audit trail) belongs to the new hospital
  if v_dom <> '' then insert into public.tenant_domains (domain, tenant_id, is_primary) values (v_dom, v_id, true); end if;
  insert into public.app_settings (tenant_id, key, data) values (v_id, 'bootstrap', jsonb_build_object('owner_email', v_owner));
  perform public.seed_hospital_defaults(v_id);
  perform public.provider_log('hospital:create', v_slug, jsonb_build_object('plan', v_plan, 'status', v_stat, 'owner', v_owner, 'domain', nullif(v_dom, '')));
  return jsonb_build_object('id', v_id, 'slug', v_slug, 'domain', nullif(v_dom, ''), 'owner_email', v_owner);
end $$;

-- edit a hospital: { name?, code?, notes?, modules?, owner_email? (until the owner has signed up) }
create or replace function public.cp_update_hospital(p_id uuid, p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants; v_owner text;
begin
  perform public.cp_require(array['admin']);
  select * into t from public.tenants where id = p_id for update;
  if not found then raise exception 'Hospital not found'; end if;
  perform set_config('app.tenant_id', p_id::text, true);
  if p ? 'name' and char_length(trim(p ->> 'name')) not between 2 and 120 then raise exception 'Enter the hospital''s name.'; end if;
  if p ? 'code' and upper(trim(p ->> 'code')) !~ '^[A-Z]{2,6}$' then raise exception 'Record prefix: 2–6 capital letters'; end if;
  if p ? 'modules' and (jsonb_typeof(p -> 'modules') <> 'object' or exists (select 1 from jsonb_each_text(p -> 'modules') m
       where m.key not in ('general', 'appearance', 'dashboard', 'notifications', 'forms', 'security', 'data', 'cms') or m.value not in ('hospital', 'provider'))) then
    raise exception 'Unknown module setting';
  end if;
  update public.tenants set
    name = coalesce(trim(p ->> 'name'), name),
    code = coalesce(upper(trim(p ->> 'code')), code),
    notes = case when p ? 'notes' then nullif(trim(p ->> 'notes'), '') else notes end,
    modules = coalesce(p -> 'modules', modules),
    updated_at = now()
  where id = p_id;
  if p ? 'owner_email' then
    v_owner := lower(trim(p ->> 'owner_email'));
    if v_owner !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Enter the owner''s e-mail.'; end if;
    if exists (select 1 from public.profiles where tenant_id = p_id and role = 'owner') then raise exception 'The owner has already signed up — change owners in the hospital''s Users & accounts.'; end if;
    insert into public.app_settings (tenant_id, key, data) values (p_id, 'bootstrap', jsonb_build_object('owner_email', v_owner))
    on conflict (tenant_id, key) do update set data = excluded.data;
  end if;
  perform public.provider_log('hospital:update', t.slug, p);
  return public.cp_hospitals(p_id) -> 0;
end $$;

-- plan, trial, wallet, manual payments, suspend for one hospital — the same function the hospital app uses
create or replace function public.cp_billing(p_id uuid, p_action text, p_args jsonb default '{}'::jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin', 'finance']);
  if not public.provider_can(p_id) then raise exception 'Hospital not found or not assigned to you.' using errcode = '42501'; end if;
  perform set_config('app.tenant_id', p_id::text, true);
  return public.provider_billing(p_action, coalesce(p_args, '{}'::jsonb));
end $$;

-- ------------------------------------------------------------------ overview
create or replace function public.cp_overview()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_role  text := public.cp_require();
  h       jsonb := public.cp_hospitals();
  v_month date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
begin
  return jsonb_build_object(
    'hospitals', jsonb_array_length(h),
    'by_status', coalesce((select jsonb_object_agg(s, n) from (select x -> 'license' ->> 'status' s, count(*) n from jsonb_array_elements(h) x where not (x ->> 'is_primary')::boolean group by 1) q), '{}'::jsonb),
    'by_plan', coalesce((select jsonb_object_agg(s, n) from (select x ->> 'plan' s, count(*) n from jsonb_array_elements(h) x where not (x ->> 'is_primary')::boolean group by 1) q), '{}'::jsonb),
    -- monthly recurring revenue: paying hospitals' monthly price (₹, before GST)
    'mrr', coalesce((select sum((x ->> 'price')::numeric) from jsonb_array_elements(h) x where x -> 'license' ->> 'status' = 'active' and not (x ->> 'is_primary')::boolean and x -> 'license' ->> 'paid_until' is not null), 0),
    'wallet_paise', coalesce((select sum((x ->> 'wallet_paise')::bigint) from jsonb_array_elements(h) x where not (x ->> 'is_primary')::boolean), 0),
    'attention', coalesce((select jsonb_agg(jsonb_build_object('id', x -> 'id', 'name', x -> 'name', 'status', x -> 'license' ->> 'status',
                              'until', coalesce(x -> 'license' ->> 'paid_until', x -> 'license' ->> 'trial_ends_at'), 'read_only_from', x -> 'license' ->> 'read_only_from'))
                          from jsonb_array_elements(h) x
                         where not (x ->> 'is_primary')::boolean and (x -> 'license' ->> 'status' in ('grace', 'read_only')
                            or (x -> 'license' ->> 'status' in ('trial', 'active')
                                and coalesce((x -> 'license' ->> 'paid_until')::timestamptz, (x -> 'license' ->> 'trial_ends_at')::timestamptz) < now() + interval '7 days'))), '[]'::jsonb),
    'payments_30d_paise', case when v_role = 'support' then null else
      (select coalesce(sum(total_paise), 0) from public.billing_payments where status = 'paid' and paid_at > now() - interval '30 days' and public.provider_can(tenant_id)) end,
    'messages', coalesce((select jsonb_object_agg(channel, n) from (select m.channel, sum(m.sent) n from public.message_usage m
                           where m.month = v_month and m.source = 'platform' and public.provider_can(m.tenant_id) group by 1) q), '{}'::jsonb),
    'leads_new', case when v_role = 'admin' then (select count(*) from public.platform_leads where status = 'new') end);
end $$;

-- ------------------------------------------------------------------ team
create or replace function public.cp_team()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return coalesce((select jsonb_agg(jsonb_build_object(
      'user_id', u.user_id, 'email', a.email, 'name', coalesce(p.full_name, split_part(a.email, '@', 1)), 'role', u.role, 'active', u.active, 'since', u.created_at,
      'hospitals', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name) order by t.name) from public.provider_assignments x join public.tenants t on t.id = x.tenant_id where x.user_id = u.user_id), '[]'::jsonb),
      'last_action', (select max(at) from public.provider_audit pa where pa.user_id = u.user_id)) order by u.active desc, u.role, a.email)
    from public.provider_users u join auth.users a on a.id = u.user_id left join public.profiles p on p.id = u.user_id), '[]'::jsonb);
end $$;

-- add / change a team member: { email, role, active, hospitals: [tenant id…] }. They sign up once first (any address).
create or replace function public.cp_save_provider(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_email  text := lower(trim(coalesce(p ->> 'email', '')));
  v_role   text := coalesce(p ->> 'role', 'support');
  v_active boolean := coalesce((p ->> 'active')::boolean, true);
  v_user   uuid;
  v_hosp   text;
begin
  perform public.cp_require(array['admin']);
  if v_role not in ('admin', 'support', 'finance') then raise exception 'Role: admin, support or finance'; end if;
  select id into v_user from auth.users where lower(email) = v_email;
  if v_user is null then raise exception 'No account with % yet — ask them to create one first (Sign up on the platform site), then add them here.', v_email; end if;
  if v_user = auth.uid() and (v_role <> 'admin' or not v_active) then raise exception 'You can''t remove your own admin access — ask another admin.'; end if;
  if not exists (select 1 from public.provider_users where user_id = v_user) then
    select t.name into v_hosp from public.profiles pr join public.tenants t on t.id = pr.tenant_id where pr.id = v_user and pr.role <> 'patient';
    if v_hosp is not null then raise exception '% is a staff account at % — one account = one hospital, please use another e-mail.', v_email, v_hosp; end if;
    -- a platform account belongs to no hospital (its sign-up created a patient record there — removed)
    perform set_config('app.tenant_id', coalesce((select tenant_id::text from public.profiles where id = v_user), ''), true);   -- audit trail stays with that hospital
    perform set_config('app.tenant_move', 'on', true);
    update public.profiles set tenant_id = null, role = 'patient' where id = v_user;
    delete from public.patients where profile_id = v_user;
    perform set_config('app.tenant_move', '', true);
    perform set_config('app.tenant_id', '', true);
  end if;
  insert into public.provider_users (user_id, role, active) values (v_user, v_role, v_active)
  on conflict (user_id) do update set role = excluded.role, active = excluded.active;
  delete from public.provider_assignments where user_id = v_user;
  if v_role <> 'admin' then
    insert into public.provider_assignments (user_id, tenant_id)
    select v_user, t.id from public.tenants t where t.id::text in (select jsonb_array_elements_text(coalesce(p -> 'hospitals', '[]'::jsonb)));
  end if;
  perform public.provider_log('team:save', v_email, jsonb_build_object('role', v_role, 'active', v_active, 'hospitals', p -> 'hospitals'));
  return jsonb_build_object('user_id', v_user);
end $$;

-- ------------------------------------------------------------------ money, audit, settings
create or replace function public.cp_payments(p_tenant uuid default null, p_limit int default 200)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin', 'finance']);
  return coalesce((select jsonb_agg(to_jsonb(b) order by b.created_at desc) from (
    select bp.id, bp.created_at, bp.tenant_id, t.name as hospital, bp.kind, bp.plan, bp.months, bp.base_paise, bp.gst_paise, bp.total_paise,
           bp.status, bp.provider, bp.method, bp.payment_id, bp.order_id, bp.paid_at, bp.invoice_no, bp.period_from, bp.period_to, bp.buyer
      from public.billing_payments bp join public.tenants t on t.id = bp.tenant_id
     where public.provider_can(bp.tenant_id) and (p_tenant is null or bp.tenant_id = p_tenant) and bp.status <> 'created'
     order by bp.created_at desc limit least(greatest(coalesce(p_limit, 200), 1), 1000)) b), '[]'::jsonb);
end $$;

create or replace function public.cp_audit(p_tenant uuid default null, p_limit int default 300)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return coalesce((select jsonb_agg(to_jsonb(a) order by a.at desc) from (
    select pa.id, pa.at, pa.user_name, pa.mode, pa.tenant_id, t.name as hospital, pa.action, pa.target, pa.detail
      from public.provider_audit pa left join public.tenants t on t.id = pa.tenant_id
     where p_tenant is null or pa.tenant_id = p_tenant
     order by pa.at desc limit least(greatest(coalesce(p_limit, 300), 1), 2000)) a), '[]'::jsonb);
end $$;

create or replace function public.cp_settings()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return jsonb_build_object('billing', public.billing_config());
end $$;

-- prices, GST, trial / grace days, message rates, seller details (merged into platform_settings 'billing')
create or replace function public.cp_save_billing_settings(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare k text; n numeric;
begin
  perform public.cp_require(array['admin']);
  if jsonb_typeof(p) <> 'object' then raise exception 'Settings must be an object'; end if;
  for k in select jsonb_object_keys(p) loop
    if k not in ('gstPercent', 'trialDays', 'graceDays', 'yearlyMonths', 'minTopup', 'maxTopup', 'ratesPaise', 'plans', 'seller') then raise exception 'Unknown setting %', k; end if;
  end loop;
  foreach k in array array['gstPercent', 'trialDays', 'graceDays', 'yearlyMonths', 'minTopup', 'maxTopup'] loop
    if p ? k then
      n := (p ->> k)::numeric;
      if n is null or n < 0 or (k = 'gstPercent' and n > 40) or (k in ('trialDays', 'graceDays') and n > 90) or (k = 'yearlyMonths' and (n < 1 or n > 12)) then
        raise exception 'The value for % is out of range.', k;
      end if;
    end if;
  end loop;
  if (p ? 'minTopup' or p ? 'maxTopup')
     and coalesce((p ->> 'minTopup')::numeric, (public.billing_config() ->> 'minTopup')::numeric) > coalesce((p ->> 'maxTopup')::numeric, (public.billing_config() ->> 'maxTopup')::numeric) then
    raise exception 'The minimum top-up is above the maximum.';
  end if;
  if p ? 'ratesPaise' and exists (select 1 from jsonb_each(p -> 'ratesPaise') r where r.key not in ('sms', 'whatsapp', 'email') or jsonb_typeof(r.value) <> 'number' or (r.value)::text::numeric not between 0 and 1000) then
    raise exception 'Message rates: paise per message, 0–1000.';
  end if;
  if p ? 'plans' and exists (select 1 from jsonb_each(p -> 'plans') x where not (public.billing_config() -> 'plans' ? x.key)) then
    raise exception 'Unknown plan';
  end if;
  update public.platform_settings set data = data
    || (p - 'plans' - 'ratesPaise' - 'seller')
    || case when p ? 'ratesPaise' then jsonb_build_object('ratesPaise', coalesce(data -> 'ratesPaise', '{}'::jsonb) || (p -> 'ratesPaise')) else '{}'::jsonb end
    || case when p ? 'seller' then jsonb_build_object('seller', coalesce(data -> 'seller', '{}'::jsonb) || (p -> 'seller')) else '{}'::jsonb end
    || case when p ? 'plans' then jsonb_build_object('plans', (select jsonb_object_agg(e.key, case when p -> 'plans' ? e.key then e.value || (p -> 'plans' -> e.key) else e.value end)
                                                                 from jsonb_each(data -> 'plans') e)) else '{}'::jsonb end
   where key = 'billing';
  perform public.provider_log('settings:billing', null, p);
  return public.billing_config();
end $$;

-- ------------------------------------------------------------------ who may call what
revoke all on function public.cp_require(text[]) from public, anon, authenticated;
revoke all on function public.cp_me(), public.cp_hospitals(uuid), public.cp_hospital(uuid), public.cp_create_hospital(jsonb), public.cp_update_hospital(uuid, jsonb),
  public.cp_billing(uuid, text, jsonb), public.cp_overview(), public.cp_team(), public.cp_save_provider(jsonb), public.cp_payments(uuid, int),
  public.cp_audit(uuid, int), public.cp_settings(), public.cp_save_billing_settings(jsonb) from public, anon;
grant execute on function public.cp_me(), public.cp_hospitals(uuid), public.cp_hospital(uuid), public.cp_create_hospital(jsonb), public.cp_update_hospital(uuid, jsonb),
  public.cp_billing(uuid, text, jsonb), public.cp_overview(), public.cp_team(), public.cp_save_provider(jsonb), public.cp_payments(uuid, int),
  public.cp_audit(uuid, int), public.cp_settings(), public.cp_save_billing_settings(jsonb) to authenticated;

commit;

